INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'multi', 'Which of these numbers must be irrational? Select all that apply.', '["√50 / √2", "√2 + √2", "√2 · √8", "3 + √5", "π − π"]'::jsonb, '[1, 3]'::jsonb, 0, 'Rational + irrational is irrational, and a nonzero rational times an irrational is irrational. √2 + √2 = 2√2 (irrational). 3 + √5 is irrational. √2·√8 = √16 = 4, π − π = 0, √50/√2 = √25 = 5 are all rational.', 1 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IA' AND t.num = 1;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'What is gcd(84, 120)?', NULL, '12'::jsonb, 0, '84 = 2²·3·7 and 120 = 2³·3·5. Take each shared prime to its LOWER power: 2²·3 = 12. (The lcm takes the higher powers: 2³·3·5·7 = 840.)', 2 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IA' AND t.num = 1;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'A jacket''s price goes up 20%, then the new price goes down 20%. Compared with the original, the final price is:', '["4% lower", "2% lower", "the same", "4% higher"]'::jsonb, '0'::jsonb, 0, 'Multiply the factors: 1.20 × 0.80 = 0.96, so the final price is 96% of the original — 4% lower. The 20% decrease is taken from a bigger number than the 20% increase was.', 3 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IA' AND t.num = 1;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'Evaluate 27^(2/3).', NULL, '9'::jsonb, 0, '27^(2/3) = (27^(1/3))² = 3² = 9. Take the root first: the numbers stay small.', 4 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IA' AND t.num = 2;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'For x > 0, (x^(1/2) · x^(1/3))^6 equals:', '["x^(1/6)", "x^1", "x^5", "x^36"]'::jsonb, '2'::jsonb, 0, 'Add exponents when multiplying: 1/2 + 1/3 = 5/6. Then raise to the 6th: (x^(5/6))^6 = x^5.', 5 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IA' AND t.num = 2;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'Which is (3.2 × 10^5)(5 × 10^−8) in scientific notation?', '["16 × 10^−3", "1.6 × 10^3", "1.6 × 10^−2", "1.6 × 10^−3"]'::jsonb, '2'::jsonb, 0, '3.2 × 5 = 16 and 10^5 · 10^−8 = 10^−3, so 16 × 10^−3 = 1.6 × 10^−2. (16 × 10^−3 is the same value but not in scientific notation: the coefficient must be at least 1 and less than 10.)', 6 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IA' AND t.num = 2;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'A runner moves at 88 feet per second. What is that in miles per hour? (5,280 ft = 1 mile)', NULL, '60'::jsonb, 0, '88 ft/s × 3600 s/h = 316,800 ft/h, ÷ 5280 ft/mi = 60 mi/h. Set the units up as fractions so the ones you don''t want cancel.', 7 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IA' AND t.num = 3;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', '(3 + 2i)(1 − i) =', '["3 − 2i", "1 − i", "5 + i", "5 − i"]'::jsonb, '3'::jsonb, 0, 'FOIL: 3 − 3i + 2i − 2i². Since i² = −1, −2i² = +2, so 3 + 2 − i = 5 − i.', 8 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IA' AND t.num = 4;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'Written as a + bi, 1/(1 + i) is:', '["−1/2 − (1/2)i", "1/2 + (1/2)i", "1 − i", "1/2 − (1/2)i"]'::jsonb, '3'::jsonb, 0, 'Multiply top and bottom by the conjugate 1 − i: (1 − i)/((1 + i)(1 − i)) = (1 − i)/(1 + 1) = 1/2 − (1/2)i.', 9 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IA' AND t.num = 4;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'x² − 6x + 5 written in vertex form is:', '["(x + 3)² − 4", "(x − 3)² + 5", "(x − 3)² − 4", "(x − 6)² − 31"]'::jsonb, '2'::jsonb, 0, 'Complete the square: x² − 6x + 9 − 9 + 5 = (x − 3)² − 4. Vertex (3, −4), so the minimum value is −4 at x = 3.', 10 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IB' AND t.num = 1;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'Which is a full factorisation of 2x³ − 18x?', '["2x(x² − 9)", "2x(x − 3)(x + 3)", "x(2x − 9)(x + 2)", "2(x − 3)(x + 3)"]'::jsonb, '1'::jsonb, 0, 'Take out the common factor 2x: 2x(x² − 9). Then x² − 9 is a difference of squares: (x − 3)(x + 3). 2x(x² − 9) is correct but not FULLY factored.', 11 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IB' AND t.num = 1;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'A school sells student tickets at $5 and adult tickets at $8. It sold 200 tickets for $1,210. How many adult tickets were sold?', NULL, '70'::jsonb, 0, 's + a = 200 and 5s + 8a = 1210. Substitute s = 200 − a: 1000 − 5a + 8a = 1210, so 3a = 210 and a = 70 (s = 130; check 650 + 560 = 1210).', 12 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IB' AND t.num = 2;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'The solution set of |2x − 3| < 5 is:', '["x < −1 or x > 4", "−1 < x < 4", "x < 4", "−4 < x < 1"]'::jsonb, '1'::jsonb, 0, '|u| < 5 means −5 < u < 5. So −5 < 2x − 3 < 5 → −2 < 2x < 8 → −1 < x < 4. ("Less than" = between; "greater than" = the two outside pieces.)', 13 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IB' AND t.num = 3;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'The solutions of x² + 4x + 13 = 0 are:', '["−4 ± 6i", "−2 ± 3", "2 ± 3i", "−2 ± 3i"]'::jsonb, '3'::jsonb, 0, 'Quadratic formula: x = (−4 ± √(16 − 52))/2 = (−4 ± √−36)/2 = (−4 ± 6i)/2 = −2 ± 3i. The discriminant is negative, so the roots are complex conjugates.', 14 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IB' AND t.num = 3;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'The line y = x + 2 meets the parabola y = x². What is the SUM of the x-coordinates of the intersection points?', NULL, '1'::jsonb, 0, 'Set them equal: x² = x + 2 → x² − x − 2 = 0 → (x − 2)(x + 1) = 0, x = 2 or −1. Sum = 1. (Shortcut: for x² + bx + c = 0 the roots add to −b = 1.)', 15 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IB' AND t.num = 4;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'What is the average rate of change of f(x) = x² from x = 1 to x = 4?', NULL, '5'::jsonb, 0, '(f(4) − f(1))/(4 − 1) = (16 − 1)/3 = 5. It is the slope of the secant line through the two points.', 16 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IB' AND t.num = 5;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'A line passes through (2, 5) and (6, −3). What is its y-intercept?', NULL, '9'::jsonb, 0, 'Slope = (−3 − 5)/(6 − 2) = −2. Then 5 = −2(2) + b, so b = 9: y = −2x + 9.', 17 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IB' AND t.num = 6;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'What is the remainder when p(x) = x³ − 2x² + 4x − 5 is divided by (x − 2)?', NULL, '3'::jsonb, 0, 'Remainder theorem: the remainder is p(2) = 8 − 8 + 8 − 5 = 3. No long division needed.', 18 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IB' AND t.num = 7;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'multi', 'For p(x) = (x − 1)²(x + 3), select ALL true statements.', '["The y-intercept is 3", "p has degree 2", "The graph crosses the x-axis at x = −3", "The graph touches the x-axis at x = 1 without crossing it", "As x → ∞, p(x) → −∞"]'::jsonb, '[0, 2, 3]'::jsonb, 0, 'Even multiplicity (the square) at x = 1 → touches and turns; odd multiplicity at x = −3 → crosses. p(0) = (1)(3) = 3. Degree = 2 + 1 = 3, leading coefficient positive, so p(x) → +∞ as x → ∞.', 19 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IB' AND t.num = 7;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'For the values where it is defined, (x² − 9)/(x² + 5x + 6) simplifies to:', '["(x + 3)/(x + 2)", "−9/(5x + 6)", "(x − 3)/(x + 2)", "(x − 3)/(x + 3)"]'::jsonb, '2'::jsonb, 0, 'Factor: (x − 3)(x + 3) / ((x + 2)(x + 3)). Cancel the common FACTOR (x + 3): (x − 3)/(x + 2), with x ≠ −3 and x ≠ −2. You can never cancel terms like the x² on their own.', 20 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IB' AND t.num = 8;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'Solving √(x + 7) = x − 5, a student squares both sides and gets x = 2 and x = 9. What is the solution set?', '["{2}", "No solution", "{9}", "{2, 9}"]'::jsonb, '2'::jsonb, 0, 'Squaring can add extraneous roots. Check each: x = 9 → √16 = 4 and 9 − 5 = 4 ✓. x = 2 → √9 = 3 but 2 − 5 = −3 ✗. Only x = 9 works.', 21 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IB' AND t.num = 9;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'The domain of f(x) = √(x − 2) / (x − 5) is:', '["x ≥ 2", "x ≥ 2 and x ≠ 5", "x > 2", "x ≠ 5"]'::jsonb, '1'::jsonb, 0, 'The square root needs x − 2 ≥ 0 → x ≥ 2. The denominator can''t be 0 → x ≠ 5. Both conditions together.', 22 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IIA' AND t.num = 1;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'multi', 'For f(x) = −(x − 1)² + 4, select ALL true statements.', '["The range is y ≥ 4", "The zeros are x = −1 and x = 3", "f is increasing for x < 1", "The maximum value is 4", "The axis of symmetry is x = −1"]'::jsonb, '[1, 2, 3]'::jsonb, 0, 'Vertex (1, 4) and it opens down, so max 4, rising to the left of x = 1, range y ≤ 4, axis x = 1. Zeros: (x − 1)² = 4 → x − 1 = ±2 → x = −1 or 3.', 23 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IIA' AND t.num = 2;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'A geometric sequence starts 3, 6, 12, … What is its 10th term?', NULL, '1536'::jsonb, 0, 'aₙ = a₁·r^(n−1) = 3·2⁹ = 3·512 = 1536.', 24 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IIA' AND t.num = 3;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'If f(x) = 2x + 3 and g(x) = x², what is f(g(−2))?', NULL, '11'::jsonb, 0, 'Inside first: g(−2) = 4. Then f(4) = 2·4 + 3 = 11. (g(f(−2)) would be g(−1) = 1 — order matters.)', 25 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IIA' AND t.num = 4;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'The inverse of f(x) = (x − 1)/3 is:', '["f⁻¹(x) = 3x + 1", "f⁻¹(x) = (x + 1)/3", "f⁻¹(x) = 3/(x − 1)", "f⁻¹(x) = 3x − 1"]'::jsonb, '0'::jsonb, 0, 'Swap and solve: x = (y − 1)/3 → 3x = y − 1 → y = 3x + 1. Check: f(f⁻¹(x)) = (3x + 1 − 1)/3 = x.', 26 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IIA' AND t.num = 4;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'The graph of g(x) = f(x − 2) + 3 is the graph of f moved:', '["2 right and 3 up", "2 right and 3 down", "2 left and 3 up", "3 right and 2 up"]'::jsonb, '0'::jsonb, 0, 'Inside the brackets acts on x and goes the ''opposite'' way: x − 2 shifts RIGHT 2. Outside +3 shifts UP 3.', 27 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IIA' AND t.num = 4;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', '$1,000 is invested at 5% interest compounded annually. To the nearest cent, what is it worth after 3 years?', NULL, '1157.63'::jsonb, 0.01, 'A = 1000(1.05)³ = 1000 × 1.157625 = $1,157.63. Exponential: the SAME FACTOR each year. Simple (linear) interest would give 1000 + 3·50 = $1,150.', 28 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IIA' AND t.num = 5;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'Evaluate log₂ 32 + log₃(1/9).', NULL, '3'::jsonb, 0, 'log₂ 32 = 5 because 2⁵ = 32. log₃(1/9) = −2 because 3⁻² = 1/9. 5 + (−2) = 3.', 29 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IIA' AND t.num = 6;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'cos(5π/6) =', '["−1/2", "−√3/2", "1/2", "√3/2"]'::jsonb, '1'::jsonb, 0, '5π/6 is 150°, in quadrant II with reference angle π/6 (30°). cos 30° = √3/2, and cosine is negative in quadrant II.', 30 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IIA' AND t.num = 7;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', '225° in radians is:', '["9π/4", "5π/3", "3π/4", "5π/4"]'::jsonb, '3'::jsonb, 0, 'Multiply by π/180: 225π/180 = 5π/4.', 31 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IIA' AND t.num = 7;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'What is the period of y = 3 sin(2x) + 1?', '["π", "4π", "π/2", "2π"]'::jsonb, '0'::jsonb, 0, 'Period = 2π/|b| = 2π/2 = π. The 3 is the amplitude (so the max is 3 + 1 = 4) and the +1 is the midline.', 32 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IIA' AND t.num = 8;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'Solve 2^(x + 1) = 48. Give x to two decimal places.', NULL, '4.58'::jsonb, 0.01, '2^(x+1) = 48 → 2^x = 24 → x = log 24 / log 2 ≈ 1.3802/0.3010 ≈ 4.585, so about 4.58 or 4.59.', 33 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IIA' AND t.num = 9;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'multi', 'Select ALL solutions of 2 sin x = 1 on 0 ≤ x < 2π.', '["π/6", "5π/6", "7π/6", "11π/6", "π/3"]'::jsonb, '[0, 1]'::jsonb, 0, 'sin x = 1/2. Sine is positive in quadrants I and II: x = π/6 and π − π/6 = 5π/6. (7π/6 and 11π/6 give −1/2.)', 34 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IIA' AND t.num = 9;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'Evaluate lim (x→3) (x² − 9)/(x − 3).', NULL, '6'::jsonb, 0, 'Direct substitution gives 0/0. Factor: (x − 3)(x + 3)/(x − 3) = x + 3 for x ≠ 3, so the limit is 3 + 3 = 6.', 35 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IIB' AND t.num = 1;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'Evaluate lim (x→∞) (3x² + 1)/(5x² − x).', NULL, '0.6'::jsonb, 0, 'Same degree top and bottom: the limit is the ratio of leading coefficients, 3/5 = 0.6.', 36 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IIB' AND t.num = 1;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'What is the slope of the tangent line to f(x) = x³ − 3x at x = 2?', NULL, '9'::jsonb, 0, 'f′(x) = 3x² − 3, so f′(2) = 12 − 3 = 9.', 37 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IIB' AND t.num = 2;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'f(x) = x² + k for x < 1 and f(x) = 3x − 1 for x ≥ 1. What value of k makes f continuous at x = 1?', NULL, '1'::jsonb, 0, 'The two pieces must meet at x = 1: 1² + k = 3(1) − 1 → 1 + k = 2 → k = 1.', 38 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IIB' AND t.num = 3;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'Evaluate ∫ from 0 to 2 of (3x² + 2x) dx.', NULL, '12'::jsonb, 0, 'Antiderivative x³ + x². At 2: 8 + 4 = 12. At 0: 0. 12 − 0 = 12.', 39 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IIB' AND t.num = 4;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'd/dx [sin(x²)] =', '["cos(2x)", "cos(x²)", "2x sin(x²)", "2x cos(x²)"]'::jsonb, '3'::jsonb, 0, 'Chain rule: the outside derivative cos(x²) times the inside derivative 2x.', 40 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IIB' AND t.num = 4;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'f(x) = x³ − 6x² + 9x + 1. What is the LOCAL MAXIMUM VALUE of f?', NULL, '5'::jsonb, 0, 'f′(x) = 3x² − 12x + 9 = 3(x − 1)(x − 3), critical points 1 and 3. f″(x) = 6x − 12: f″(1) = −6 < 0 → local max at x = 1. f(1) = 1 − 6 + 9 + 1 = 5. (Local min at x = 3, f(3) = 1; inflection at x = 2.)', 41 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IIB' AND t.num = 5;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'Two parallel lines are cut by a transversal. Alternate interior angles measure (3x + 10)° and (5x − 30)°. What is x?', NULL, '20'::jsonb, 0, 'Alternate interior angles are congruent: 3x + 10 = 5x − 30 → 40 = 2x → x = 20 (each angle 70°).', 42 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'III' AND t.num = 1;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'What is the measure, in degrees, of each interior angle of a regular octagon?', NULL, '135'::jsonb, 0, 'Interior angle sum = (n − 2)·180 = 6·180 = 1080. ÷ 8 = 135°. (Or: each exterior angle is 360/8 = 45°, so interior = 180 − 45.)', 43 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'III' AND t.num = 2;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'The point (3, −2) is rotated 90° counterclockwise about the origin. Its image is:', '["(2, 3)", "(2, −3)", "(−3, 2)", "(−2, 3)"]'::jsonb, '0'::jsonb, 0, 'A 90° counterclockwise rotation sends (x, y) to (−y, x): (3, −2) → (2, 3). (−2, 3) is the reflection over y = x.', 44 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'III' AND t.num = 3;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'Two similar triangles have corresponding sides in the ratio 2 : 5. The smaller has area 12. What is the larger''s area?', NULL, '75'::jsonb, 0, 'Areas scale by the SQUARE of the side ratio: (5/2)² = 25/4. 12 × 25/4 = 75. (Volumes would scale by the cube.)', 45 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'III' AND t.num = 4;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'multi', 'Which conditions, on their own, are enough to prove a quadrilateral is a parallelogram? Select all that apply.', '["One pair of opposite angles is congruent", "The diagonals bisect each other", "The diagonals are perpendicular", "Both pairs of opposite sides are congruent", "One pair of opposite sides is both parallel and congruent"]'::jsonb, '[1, 3, 4]'::jsonb, 0, 'The first three are standard parallelogram tests. One pair of congruent opposite angles is not enough (a kite can have it), and perpendicular diagonals describe kites and rhombuses, not every parallelogram.', 46 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'III' AND t.num = 5;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'In triangle ABC, a = 5, b = 7 and angle C = 60°. Find c to two decimal places.', NULL, '6.24'::jsonb, 0.01, 'Law of Cosines: c² = 25 + 49 − 2(5)(7)cos 60° = 74 − 35 = 39, so c = √39 ≈ 6.245.', 47 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'III' AND t.num = 6;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'An inscribed angle intercepts an arc of 110°. What is the inscribed angle''s measure in degrees?', NULL, '55'::jsonb, 0, 'An inscribed angle is half its intercepted arc: 110/2 = 55°. (A central angle equals its arc.)', 48 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'III' AND t.num = 7;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'The circle x² + y² − 6x + 4y − 12 = 0 has:', '["center (3, −2), radius √12", "center (−3, 2), radius 5", "center (6, −4), radius 12", "center (3, −2), radius 5"]'::jsonb, '3'::jsonb, 0, 'Complete the square: (x² − 6x + 9) + (y² + 4y + 4) = 12 + 9 + 4 → (x − 3)² + (y + 2)² = 25.', 49 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'III' AND t.num = 8;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'Point P lies on the segment from A(1, 2) to B(7, 10) with AP : PB = 1 : 3. P is:', '["(3, 14/3)", "(4, 6)", "(2.5, 4)", "(5.5, 8)"]'::jsonb, '2'::jsonb, 0, 'P is 1/4 of the way from A to B: (1 + ¼·6, 2 + ¼·8) = (2.5, 4). (4, 6) is the midpoint.', 50 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'III' AND t.num = 8;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'What is the area of a regular hexagon with side length 4? Round to two decimal places.', NULL, '41.57'::jsonb, 0.01, 'A regular hexagon is 6 equilateral triangles: 6 · (√3/4)·4² = 24√3 ≈ 41.57.', 51 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'III' AND t.num = 9;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'Every dimension of a cone is doubled. Its volume is multiplied by:', '["2", "4", "8", "6"]'::jsonb, '2'::jsonb, 0, 'V = (1/3)πr²h. Doubling r and h: (2r)²(2h) = 8r²h. Any solid scaled by k has volume scaled by k³.', 52 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'III' AND t.num = 10;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'Which study design best supports a cause-and-effect conclusion?', '["A census of the whole population", "A randomized controlled experiment", "An observational study of a large sample", "A voluntary-response survey"]'::jsonb, '1'::jsonb, 0, 'Random assignment to treatments is what balances other variables between groups. Observational data, however large, can only show association.', 53 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IV' AND t.num = 1;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'Data: 2, 4, 4, 5, 7, 8, 12. A new value, 50, is added. Which statement is true?', '["The median changes much more than the mean", "Neither changes", "Both change by the same amount", "The mean changes much more than the median"]'::jsonb, '3'::jsonb, 0, 'Before: mean 42/7 = 6, median 5. After: mean 92/8 = 11.5, median (5 + 7)/2 = 6. The mean is pulled by outliers; the median is resistant.', 54 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IV' AND t.num = 2;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'Of 200 students, 80 play a sport; 30 of those are in the band. Of the 120 who don''t play a sport, 50 are in the band. What is P(band | sport)? Give a decimal.', NULL, '0.375'::jsonb, 0.001, 'Condition on the sport players only: 30 of 80 → 30/80 = 0.375. The ''given'' group is the denominator. (Here P(sport | band) is also 30/80, because the band happens to total 30 + 50 = 80 — in general the two are different.)', 55 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IV' AND t.num = 3;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'A regression of test score (y) on hours studied (x) gives ŷ = 2.5x + 40. The best interpretation of 2.5 is:', '["A student who studies 0 hours scores 2.5", "2.5% of the variation in scores is explained by hours", "Each additional hour studied is associated with a predicted score 2.5 points higher", "Studying causes scores to rise 2.5 points per hour"]'::jsonb, '2'::jsonb, 0, 'The slope is the predicted change in y per one-unit increase in x. ''Causes'' is too strong for observational data, 40 is the intercept, and variation explained is r².', 56 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IV' AND t.num = 4;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'A and B are independent with P(A) = 0.3 and P(B) = 0.5. What is P(A or B)?', NULL, '0.65'::jsonb, 0.001, 'Independent → P(A and B) = 0.3 × 0.5 = 0.15. Addition rule: 0.3 + 0.5 − 0.15 = 0.65.', 57 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IV' AND t.num = 5;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'How many different 3-person committees can be chosen from 10 people?', NULL, '120'::jsonb, 0, 'Order doesn''t matter: C(10, 3) = 10·9·8/(3·2·1) = 120. (If the 3 seats were president/VP/secretary, order matters: 10·9·8 = 720.)', 58 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IV' AND t.num = 6;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'How many distinct arrangements are there of the letters in MISSISSIPPI?', NULL, '34650'::jsonb, 0, '11 letters with I×4, S×4, P×2: 11!/(4!·4!·2!) = 39,916,800/(24·24·2) = 34,650.', 59 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IV' AND t.num = 6;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'A game costs $2. You roll one die and win $6 on a 6, nothing otherwise. What is the expected value of playing, in dollars?', NULL, '-1'::jsonb, 0, 'E = (1/6)(6) − 2 = 1 − 2 = −$1 per game. A negative expected value means you lose on average.', 60 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IV' AND t.num = 7;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'numeric', 'Scores are normal with mean 70 and standard deviation 8. About what percent of scores lie between 62 and 86?', NULL, '81.5'::jsonb, 0.5, '62 is 1 SD below, 86 is 2 SD above. Empirical rule: mean to −1 SD ≈ 34%, mean to +2 SD ≈ 47.5%. 34 + 47.5 = 81.5%.', 61 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'IV' AND t.num = 8;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'A student asks why a⁰ = 1 (for a ≠ 0). Which explanation is mathematically valid?', '["Because a⁰ means a multiplied by itself zero times, which is a", "It''s a rule to memorise; there is no reason", "Any number times zero is zero, and the zero in the exponent makes the answer 1", "aⁿ/aⁿ = 1, and by the quotient rule aⁿ/aⁿ = aⁿ⁻ⁿ = a⁰, so a⁰ must be 1 for the rules to stay consistent"]'::jsonb, '3'::jsonb, 0, 'Keep the exponent laws working: dividing a power by itself gives 1 and gives a⁰. The pattern a³ = a·a·a, a² = a³/a, a¹ = a²/a, a⁰ = a¹/a = 1 is another valid route.', 62 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'T1' AND t.num = 1;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'A student claims (a + b)² = a² + b² for all numbers. Which example best shows the claim is false?', '["a = 1, b = 1: (1 + 1)² = 4 but 1² + 1² = 2", "a = 3, b = 0: both sides equal 9", "a = 0, b = 5: both sides equal 25", "a = −2, b = 0: both sides equal 4"]'::jsonb, '0'::jsonb, 0, 'A counterexample must make the two sides DIFFERENT. Any choice with a or b = 0 makes them equal (the missing 2ab is 0), so it ''confirms'' the misconception.', 63 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'T2' AND t.num = 10;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'A student ''simplifies'' 16/64 by crossing out the 6s and gets 1/4. What is the best teacher response?', '["The answer is right but the method is invalid — try 12/24: crossing out the 2s gives 1/4, but 12/24 = 1/2", "Mark it correct since 16/64 = 1/4", "Tell the student crossing out digits always works for two-digit numbers", "Ask the student to check 16/64 on a calculator"]'::jsonb, '0'::jsonb, 0, 'A correct answer can mask incorrect thinking. Cancelling works on common FACTORS (16/64 = 16/(16·4)), not digits; a counterexample shows the method fails.', 64 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'T4' AND t.num = 21;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'Which area model correctly represents (x + 3)(x + 2)?', '["Two rectangles, x by 3 and x by 2, side by side", "A rectangle x + 3 by x + 2, split into x², 3x, 2x and 6", "A square of side x + 5", "A rectangle x by 5 plus a 3-by-2 rectangle"]'::jsonb, '1'::jsonb, 0, 'Each part of one side multiplies each part of the other: x·x + x·2 + 3·x + 3·2 = x² + 5x + 6.', 65 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'T3' AND t.num = 12;
INSERT INTO study_questions (topic_id, kind, prompt, choices, answer, tolerance, solution, sort_order) SELECT t.id, 'single', 'Asked to solve x² = 9, a student writes x = 3. Which misconception is most likely?', '["The student confused 9 with 3²", "The student thinks x² means 2x", "The student treats ''take the square root'' as giving only the principal (positive) root", "The student divided both sides by x"]'::jsonb, '2'::jsonb, 0, '√9 = 3 (principal root), but x² = 9 has two solutions, x = ±3, because (−3)² = 9 too. Students often carry the √ symbol''s ''positive only'' meaning into solving.', 66 FROM study_topics t JOIN study_areas a ON a.id = t.area_id JOIN study_exams e ON e.id = a.exam_id WHERE e.code = 'praxis-5165' AND a.code = 'T4' AND t.num = 15;
