-- 1937 — 🎓 Study (#study): a person's study plan for a test, first one the
-- owner's Praxis Mathematics (5165) for the PA Mathematics 7-12 certificate.
--
-- Owner 2026-11-26: "i need a project on fh lol to prepare for the math 7-12
-- praxis for pa so i can teach it" · "this is an example of how fh can help
-- players/coaches beyond football".
--
-- So a plan belongs to a PERSON, not to the owner: any player or coach can be
-- given one (a study_plans row) and the 🎓 Learn menu shows the page to them
-- (trigger below adds the menu_page_people row).  Today only person 1 has one.
--
--   study_exams          the test: time, questions, calculator, passing score
--   study_areas          its content categories (I, IA, IB … from the ETS
--                        Study Companion) + the Tasks of Teaching overlay
--   study_topics         the numbered topics under each area
--   study_topic_points   the lettered points under each topic
--   study_questions      practice questions, FH originals with worked
--                        solutions (ETS's sample questions are not copied —
--                        the page links to the Study Companion instead)
--   study_plans          a person + an exam + their test date
--   study_topic_marks    how the person rates each topic: learning / confident
--   study_answers        every practice answer, right or wrong
--
-- Outline source: ETS, Praxis Study Companion, Mathematics (5165),
-- https://praxis.ets.org/on/demandware.static/-/Library-Sites-ets-praxisLibrary/default/pdfs/5165.pdf
-- Passing score 159 (Pennsylvania): Mercyhurst University 2025 content-area
-- testing requirements and Wilkes University testing guide — re-check on
-- praxis.ets.org / PDE before registering.

BEGIN;

CREATE TABLE study_exams (
    id               serial PRIMARY KEY,
    code             text NOT NULL UNIQUE,
    title            text NOT NULL,
    provider         text NOT NULL,
    test_code        text,
    minutes          integer,
    question_count   integer,
    formats          text,
    calculator       text,
    score_min        integer,
    score_max        integer,
    pass_score       integer,
    pass_score_state text,
    pass_score_source text,
    companion_url    text,
    register_url     text,
    note             text
);

CREATE TABLE study_areas (
    id               serial PRIMARY KEY,
    exam_id          integer NOT NULL REFERENCES study_exams(id) ON DELETE CASCADE,
    parent_id        integer REFERENCES study_areas(id) ON DELETE CASCADE,
    code             text NOT NULL,
    name             text NOT NULL,
    approx_questions integer,
    pct              integer,
    -- the Tasks of Teaching run ACROSS the content (~25% of questions), not beside it
    is_overlay       boolean NOT NULL DEFAULT false,
    sort_order       integer NOT NULL DEFAULT 0,
    UNIQUE (exam_id, code)
);

CREATE TABLE study_topics (
    id          serial PRIMARY KEY,
    area_id     integer NOT NULL REFERENCES study_areas(id) ON DELETE CASCADE,
    num         integer NOT NULL,
    statement   text NOT NULL,
    sort_order  integer NOT NULL DEFAULT 0,
    UNIQUE (area_id, num)
);

CREATE TABLE study_topic_points (
    id          serial PRIMARY KEY,
    topic_id    integer NOT NULL REFERENCES study_topics(id) ON DELETE CASCADE,
    letter      text NOT NULL,
    statement   text NOT NULL,
    sort_order  integer NOT NULL DEFAULT 0,
    UNIQUE (topic_id, letter)
);

CREATE TABLE study_question_kinds (
    code   text PRIMARY KEY,
    label  text NOT NULL
);

CREATE TABLE study_questions (
    id          serial PRIMARY KEY,
    topic_id    integer NOT NULL REFERENCES study_topics(id) ON DELETE CASCADE,
    kind        text NOT NULL REFERENCES study_question_kinds(code),
    prompt      text NOT NULL,
    -- single / multi: the choices, in order; numeric: NULL
    choices     jsonb,
    -- single: the right index; multi: array of right indexes; numeric: the number
    answer      jsonb NOT NULL,
    tolerance   numeric NOT NULL DEFAULT 0,
    solution    text NOT NULL,
    source      text NOT NULL DEFAULT 'Football Home original',
    is_active   boolean NOT NULL DEFAULT true,
    sort_order  integer NOT NULL DEFAULT 0,
    CHECK ((kind = 'numeric') = (choices IS NULL))
);

CREATE TABLE study_plans (
    id          serial PRIMARY KEY,
    person_id   integer NOT NULL REFERENCES persons(id) ON DELETE CASCADE,
    exam_id     integer NOT NULL REFERENCES study_exams(id) ON DELETE CASCADE,
    test_date   date,
    created_at  timestamptz NOT NULL DEFAULT now(),
    UNIQUE (person_id, exam_id)
);

CREATE TABLE study_topic_marks (
    plan_id     integer NOT NULL REFERENCES study_plans(id) ON DELETE CASCADE,
    topic_id    integer NOT NULL REFERENCES study_topics(id) ON DELETE CASCADE,
    status      text NOT NULL CHECK (status IN ('learning', 'confident')),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (plan_id, topic_id)
);

CREATE TABLE study_answers (
    id           serial PRIMARY KEY,
    plan_id      integer NOT NULL REFERENCES study_plans(id) ON DELETE CASCADE,
    question_id  integer NOT NULL REFERENCES study_questions(id) ON DELETE CASCADE,
    given        jsonb NOT NULL,
    is_correct   boolean NOT NULL,
    answered_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX study_answers_plan_idx ON study_answers (plan_id, question_id);

-- ── Menu: 🎓 Learn → Study, shown only to people with a plan ──────────────
ON CONFLICT (code) DO NOTHING;
VALUES ('study', 'learn', 'Study', '🎓', 'named', 1, '{study}', false, false, true)
ON CONFLICT (code) DO NOTHING;

CREATE OR REPLACE FUNCTION fh_study_plan_menu() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    ON CONFLICT DO NOTHING;
    RETURN NEW;
END $$;
CREATE TRIGGER study_plans_menu AFTER INSERT ON study_plans
    FOR EACH ROW EXECUTE FUNCTION fh_study_plan_menu();

-- ── The exam ──────────────────────────────────────────────────────────────
                         score_min, score_max, pass_score, pass_score_state, pass_score_source, companion_url, register_url, note)
VALUES ('praxis-5165', 'Praxis Mathematics (5165)', 'ETS', '5165', 180, 66,
        'Selected response (one or more answers), numeric entry, other types. About 25% of questions put the maths in a teaching scenario. Some questions may not count.',
        'On-screen graphing calculator; formulas + notation on the Help screen. Bring your own: not allowed.',
        100, 200, 159, 'PA',
        'Mercyhurst 2025 + Wilkes testing guides (PA Mathematics 7-12). Re-check on praxis.ets.org before registering.',
        'https://praxis.ets.org/on/demandware.static/-/Library-Sites-ets-praxisLibrary/default/pdfs/5165.pdf',
        'https://praxis.ets.org/test/5165.html',
        'PA Mathematics 7-12 certificate.');

-- ── The outline (ETS Study Companion 5165, Content Topics + Tasks of Teaching) ──

-- ── Practice questions (Football Home originals, worked solutions) ──

-- ── The owner's plan (test date set on the page) ───────────────────────────
SELECT 1, id FROM study_exams WHERE code = 'praxis-5165';

